<?php require_once __DIR__.'/verificar_admin.php';require_once __DIR__.'/../config/conexion.php';
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){validar_token();$nombre=trim((string)($_POST['nombre']??''));if(mb_strlen($nombre)<2||mb_strlen($nombre)>100)$error='El nombre debe tener entre 2 y 100 caracteres.';else try{$q=$pdo->prepare('INSERT INTO categorias_juego(nombre) VALUES(?)');$q->execute([$nombre]);ir('categorias.php?ok=1');}catch(PDOException $x){$error='La categoría ya existe o no pudo guardarse.';}}
$categorias=$pdo->query('SELECT c.id_categoria,c.nombre,COUNT(j.id_juego) total FROM categorias_juego c LEFT JOIN juegos j ON j.id_categoria=c.id_categoria GROUP BY c.id_categoria,c.nombre ORDER BY c.nombre')->fetchAll();$titulo_pagina='Categorías';require __DIR__.'/../includes/header.php';?><section class="page-title"><span class="eyebrow">ORGANIZACIÓN</span><h1>Categorías</h1><p>Creá categorías para organizar los juegos del catálogo.</p></section><?php require __DIR__.'/_nav.php';?><section class="two-column"><article class="form-panel"><h2>Nueva categoría</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['ok'])):?><div class="alert alert-success">Categoría guardada.</div><?php endif;?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Nombre<input name="nombre" maxlength="100" required></label><button class="btn btn-primary" type="submit">Guardar categoría</button></form></article><article class="panel-card"><h2>Categorías existentes</h2><div class="category-list"><?php foreach($categorias as $c):?><div><strong><?=e($c['nombre'])?></strong><span><?=e($c['total'])?> juegos</span></div><?php endforeach;?></div></article></section><?php require __DIR__.'/../includes/footer.php';?>